import{_ as s,o as e,c as p,a3 as n}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"龙泡泡基建活动相关事项","description":"","frontmatter":{"translationSource":{"title":"龙泡泡基建活动相关事项","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1cmRL9Ya06LDbO5jjC7IO1","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/chubby-lung-factory-event-notes"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/chubby-lung-factory-event-notes"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/chubby-lung-factory-event-notes"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/chubby-lung-factory-event-notes"}]]},"headers":[],"relativePath":"zh/chubby-lung-factory-event-notes.md","filePath":"zh/page-1cmRL9Ya06LDbO5jjC7IO1.md"}'),r={name:"zh/chubby-lung-factory-event-notes.md"};function o(i,a,t,c,l,d){return e(),p("div",null,[...a[0]||(a[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="龙泡泡基建活动相关事项" aria-hidden="true"></span><h1 id="龙泡泡基建活动相关事项" tabindex="-1">龙泡泡基建活动相关事项 <a class="header-anchor" href="#龙泡泡基建活动相关事项" aria-label="Permalink to &quot;龙泡泡基建活动相关事项&quot;">​</a></h1><blockquote><p>源页面 ID：<code>1cmRL9Ya06LDbO5jjC7IO1</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1cmRL9Ya06LDbO5jjC7IO1" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-blue">大泡泡不需要造小泡泡解锁！</span></p><p><span id="source-block-7e8C3Zzko6WKfXPxBCBf8j"></span></p><span class="logistics-source-anchor" id="数据汇总" aria-hidden="true"></span><h2 id="数据汇总" tabindex="-1">数据汇总 <a class="header-anchor" href="#数据汇总" aria-label="Permalink to &quot;数据汇总&quot;">​</a></h2><p><a href="/endfield-skydoc/zh/aic-information-from-previews">前瞻基建相关信息</a></p><p><span id="source-block-6Sj9AUEZFFAsbRczpICbbP"></span></p><span class="logistics-source-anchor" id="配方" aria-hidden="true"></span><h2 id="配方" tabindex="-1">配方 <a class="header-anchor" href="#配方" aria-label="Permalink to &quot;配方&quot;">​</a></h2><p><span id="source-block-vgo5MejFCuh7TN7RM6wSHH"></span></p><span class="logistics-source-anchor" id="原始配方" aria-hidden="true"></span><h4 id="原始配方" tabindex="-1">原始配方 <a class="header-anchor" href="#原始配方" aria-label="Permalink to &quot;原始配方&quot;">​</a></h4><p>1息壤=1实验息壤块（精炼炉，2s）</p><p>1实验息壤块=1实验龙泡泡外壳（塑形机，2s）</p><p>4赤铜零件+1息壤=1实验铜骨骼（封装机，2s）</p><p>5实验龙泡泡外壳+5实验铜骨骼=1息壤龙泡泡（封装机，10s）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5cf756bf75d5dc98.q90-beb351b6975f0822.webp" alt="龙泡泡基建活动相关事项"></p><hr><p>1重息壤=1实验重息壤块（精炼炉，10s）</p><p>1实验重息壤块+5惰气=1实验龙泡泡重壳（塑形机，10s）</p><p>2赤铜气+1息壤气=1实验息壤铜气（气体反应炉，2s）</p><p>1实验息壤铜气=1实验息壤铜锭（固气转化机，2s）</p><p>5实验息壤铜锭=1实验息壤铜零件（配件机，10s）</p><p>1实验息壤铜零件+1重息壤=1实验息壤铜骨骼（封装机，10s）</p><p>1实验龙泡泡重壳+1实验息壤铜骨骼=1重息壤龙泡泡（封装机，10s）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e9c26224aa0cf35e.q90-5027f8a60a5a5bb1.webp" alt="龙泡泡基建活动相关事项"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5e2151617917471d.q90-c1dbb6bf0b9a65d3.webp" alt="龙泡泡基建活动相关事项"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-de18758df159c540.q90-c0e22dbcd0bf5e4f.webp" alt="龙泡泡基建活动相关事项"></p><p><span id="source-block-iWRGnAIK07Gn9EQZ6TC3kW"></span></p><span class="logistics-source-anchor" id="整理后配方" aria-hidden="true"></span><h4 id="整理后配方" tabindex="-1">整理后配方 <a class="header-anchor" href="#整理后配方" aria-label="Permalink to &quot;整理后配方&quot;">​</a></h4><p>1息壤龙泡泡=20铜+10息壤</p><p>1重息壤龙泡泡=10铜气+6息壤气+2重息壤+5惰气</p><p>=20铜+9.2息壤+2重息壤+5惰气（液气路线，铜固气为9.6息壤，都固气为10息壤）</p><p>单核重息壤龙泡泡6/m=每分钟120铜+55.2息壤+12重息壤+30惰气</p><p>单个龙泡泡原料： 20铜 10息壤 价值100 25铜 24.9息壤 7.5惰气 价值200</p><p><span id="source-block-BeJgoP86Dz7Q1PtXpT6hm7"></span></p><span class="logistics-source-anchor" id="据点产值和售价" aria-hidden="true"></span><h3 id="据点产值和售价" tabindex="-1">据点产值和售价 <a class="header-anchor" href="#据点产值和售价" aria-label="Permalink to &quot;据点产值和售价&quot;">​</a></h3><p>大龙泡泡：200调度券+20援助券</p><p>小龙泡泡：100调度券+10援助券</p><p>灼铜零件70=25铜块+11.8息壤（液气，双核灼铜，四核为11.75息壤）</p><p>赫铜零件48=25铜块+5.7息壤（液气）</p><p>重息壤27=2.5铜块+7.85息壤（液气）</p><p>铜药22=20铜块</p><p>每小时据点产值：4级天王坪42000+4级心脏站27360+4级应天台33600=102960合每分钟1716</p><p>基础积累速度分别为30000，22800，24000，合计76800/h=1280/m</p><p>产卷倍率加成在两阶段均为0.25（一阶段0.25，二阶段0.5，按叠加计算）</p><p><strong>增产25%后每分钟1716+1280*0.25=2036</strong></p><p><strong>增产50%后每分钟1716+1280*0.5=2356</strong></p><p><span id="source-block-QXCjpc23yJHwd8F6sM0A8p"></span></p><span class="logistics-source-anchor" id="其他相关数据" aria-hidden="true"></span><h3 id="其他相关数据" tabindex="-1">其他相关数据 <a class="header-anchor" href="#其他相关数据" aria-label="Permalink to &quot;其他相关数据&quot;">​</a></h3><p><span id="source-block-hMWr1YFKh1dwaMFy15t1FG"></span></p><span class="logistics-source-anchor" id="活动开启时间" aria-hidden="true"></span><h4 id="活动开启时间" tabindex="-1">活动开启时间 <a class="header-anchor" href="#活动开启时间" aria-label="Permalink to &quot;活动开启时间&quot;">​</a></h4><p>2026/9/16 12:00:00一阶段</p><p>2026/9/23 4:00:00二阶段</p><p>2026/9/30 16:00:00活动配方关闭</p><p>2026/10/7 4:00:00商店关闭</p><p>一阶段共6天16小时=160小时=<strong>9600分钟</strong>，二阶段共7天12小时=180小时=<strong>10800分钟</strong></p><p><span id="source-block-7ezBftIvbb1FuDyNaZDYST"></span></p><span class="logistics-source-anchor" id="活动商店援助券价格" aria-hidden="true"></span><h4 id="活动商店援助券价格" tabindex="-1">活动商店援助券价格 <a class="header-anchor" href="#活动商店援助券价格" aria-label="Permalink to &quot;活动商店援助券价格&quot;">​</a></h4><p><a href="/endfield-skydoc/zh/shop-contents">商店内容</a></p><details><summary>蚀刻章</summary><p>蚀刻章<br> 龙泡泡大爆发<br> 伟大的龙泡泡，其足迹遍布大地。出击，出击！<br> 于「集成援助·泡泡出击」期间累计获得800000张援助成果券<br> 于「集成援助·泡泡出击」期间累计获得800000张援助成果券，且累计提交20000个重息壤龙泡泡</p></details><p><span id="source-block-01lA8uksMqSOaDfGa5DAIc"></span></p><span class="logistics-source-anchor" id="价值分析与生产方案" aria-hidden="true"></span><h2 id="价值分析与生产方案" tabindex="-1">价值分析与生产方案 <a class="header-anchor" href="#价值分析与生产方案" aria-label="Permalink to &quot;价值分析与生产方案&quot;">​</a></h2><p><span id="source-block-e18QBofdmV4q2fGlExA2mN"></span></p><span class="logistics-source-anchor" id="生产方案" aria-hidden="true"></span><h3 id="生产方案" tabindex="-1">生产方案 <a class="header-anchor" href="#生产方案" aria-label="Permalink to &quot;生产方案&quot;">​</a></h3><p><span class="mark-red">方案1：</span></p><p>最简方案：一阶段小龙泡泡一条产线随便产一点用来解锁二阶段龙泡泡，二阶段大龙泡泡两条满速产线，即使活动二阶段开始一天才搭好也有二阶段20<em>12</em>60<em>24</em>6.5=2246400的活动券，完全足以换完商店</p><p>或者俩条小龙泡泡，2,180,800÷10÷12÷60÷24&lt;13天，即使一阶段快过一半也来得及</p><p><span class="mark-red">方案2：</span>（搬空商店，且拿到蚀刻章镀层）</p><p>原产线基础上一阶段需生产411400/10=<strong>41140</strong>个<span class="mark-green">息壤龙泡泡</span>，合<strong>4.285</strong>个/min；二阶段仍需生产1769400/20=<strong>88470</strong>个<span class="mark-sky_blue">重息壤龙泡泡</span>，合<strong>8.777</strong>个/min。</p><p>推荐生产方案：（基础 14.75电 12灼 24重）</p><p>一阶段：<strong>1</strong>条满速<span class="mark-green">息壤龙泡泡</span>；</p><p>二阶段：1**.5**条满速<span class="mark-sky_blue">重息壤龙泡泡</span></p><p><span class="mark-grey"><em>ps：二阶段的1.5条重息壤龙泡泡的赤铜矿消耗为180/min，加上双灼双重的产线消耗360/min超出矿物产出。解决方法有四种：</em></span></p><p><span class="mark-grey"><em>1.不管，此时全部含原料赤铜块的产线减速至94.44%。但存在风险：由于产线模式的不同，可能会导致灼铜模块堵塞酸气停产；</em></span></p><p><span class="mark-grey"><em>2.关闭一条灼铜模块的赤铜块转赤铜气的出货口。但同样存在风险，同上；</em></span></p><p><span class="mark-grey"><em>3.关闭一条重息壤龙泡泡的铜矿输出，将产速从9/min将至7.5/min，活动期间活动代币产量为(100<em>9600</em>6+200<em>10800</em>7.5)/10＝2196000＞2180800，依然可以换完商店；</em></span></p><p><span class="mark-grey"><em>4.在3的基础上，如担心各种原因亏损少量产能，导致代币不足，可短期内自行增加产线模块，消耗库存。</em></span></p><p><span class="mark-red">方案3：</span>（只用活动产物换券）</p><p>原产线基础上一阶段需生产19545600/100=<strong>195456</strong>个<span class="mark-green">息壤龙泡泡</span>，合<strong>19.390</strong>个/min；二阶段仍需生产21988800/200=<strong>109944</strong>个<span class="mark-sky_blue">重息壤龙泡泡</span>，合<strong>10.901</strong>个/min。（0.25叠加至0.5：二阶段仍需生产25444800/200=127224个<span class="mark-sky_blue">重息壤龙泡泡</span>，合11.78个/min）</p><p>推荐生产方案：（基础 14.75电池 24重息壤）</p><p>一阶段：<strong>3.232</strong>条满速<span class="mark-green">息壤龙泡泡</span></p><p>二阶段：1.817条满速<span class="mark-sky_blue">重息壤龙泡泡</span>（1.963）</p><p><span class="mark-red">方案4：</span>（叛逆！优先换灼铜零件，重息壤，中容武陵电池）</p><p>1.4-1.5摆烂基建（14.75电+18灼+24重，3电池用来发电）原产线基础上一阶段仍需生产**-48624<strong>个<span class="mark-green">息壤龙泡泡</span>，合</strong>-5.065<strong>个/min；二阶段仍需生产</strong>-27351**个<span class="mark-sky_blue">重息壤龙泡泡</span>，<strong>合-2.5325</strong>个/min。</p><p>推荐生产方案：<span class="mark-red"><strong>（你玩不玩？？？不推荐！！！）</strong></span></p><p><span class="mark-grey"><em>ps：至于为什么会有息壤和铜块放生，是因为这里只给出比较容易实现的方案。那如果想完美利用所有资源怎么办呢？</em></span><span class="mark-orange"><em>当然是交给我们伟大的自适应产线啦！</em></span></p><p><span id="source-block-53ZUn1aG2hgB3KMJjCb5sb"></span></p><span class="logistics-source-anchor" id="蓝图" aria-hidden="true"></span><span class="logistics-source-anchor" id="blueprints-continuously-updated" aria-hidden="true"></span><span class="logistics-source-anchor" id="蓝图-持续更新" aria-hidden="true"></span><h2 id="蓝图" tabindex="-1">蓝图 <a class="header-anchor" href="#蓝图" aria-label="Permalink to &quot;蓝图&quot;">​</a></h2><p>官方版本小龙泡泡：EF01eaA7oaeAa4A6ioAi8</p><p>官方版本大龙泡泡：EF018OI3eO8IO1Aa4UI73</p><p>半速小龙泡泡：EF01u28IU2u820ei4AoOU</p><p>半速大龙泡泡：EF013Eou7E3oEa9IO0579</p><p>半速小龙泡泡（精炼）：EF015i2O1i52iu92OeIoe</p><p>半速大龙泡泡（精炼）：EF01A67iu6A76Ee169ieO</p><p>满速大龙泡泡：EF018OI3eO8IO1A63UI73</p><p>极限压缩9/min大龙泡泡：EF01u28IU2u820eEeAoOU</p><p><span class="mark-grey"><em>除官方大龙泡泡需要外接息壤气，其余蓝图只需要接水，惰气，污水暗管（废水处理机）</em></span></p><p>Ko鸟自用分离式蓝图</p><p>[A]两台固化机 EF015i2O1i52iu9OAeIoe</p><p>[B]12大龙泡泡封装 EF01u28IU2u820eUEAoOU</p><p>[C]4核气体反应 EF01ao605oa6oA41aoe5e</p><p>[D]两台气化机赤铜气 EF018OI3eO8IO1A66UI73</p><p>2A+1B+0.5C+1D=12/m重息壤龙泡泡，输入24+12+60=96息壤气，66240铜</p></div>',1)])])}const m=s(r,[["render",o]]);export{u as __pageData,m as default};
